<?php

declare(strict_types=1);
require_once __DIR__.'/../../includes/module-admin.php';$pdo=cmsAdminModuleBoot('content');$base='/admin/content.php';
if($_SERVER['REQUEST_METHOD']==='POST'){cmsVerifyCsrf();$action=cmsStr($_POST['action']??'save',30);$id=cmsInt($_POST['id']??0);
 if($action==='delete'&&$id>0){$s=$pdo->prepare('DELETE FROM site_content WHERE id=:id');$s->execute([':id'=>$id]);cmsAudit('content.delete','site_content',(string)$id);cmsAdminRedirect($base,'تم الحذف.');}
 if($action==='toggle'&&$id>0){$s=$pdo->prepare('UPDATE site_content SET is_active=1-is_active WHERE id=:id');$s->execute([':id'=>$id]);cmsAudit('content.toggle','site_content',(string)$id);cmsAdminRedirect($base,'تم تحديث الحالة.');}
 $key=cmsSlug(cmsStr($_POST['content_key']??'',160));$group=cmsSlug(cmsStr($_POST['group_key']??'general',100))?:'general';$label=cmsStr($_POST['label']??'',190);$ar=cmsStr($_POST['value_ar']??'');$en=cmsStr($_POST['value_en']??'');$type=in_array($_POST['input_type']??'text',['text','textarea','html'],true)?$_POST['input_type']:'text';$sort=cmsInt($_POST['sort_order']??0);$active=cmsBool($_POST['is_active']??0);
 if($key===''||$label==='')cmsAdminRedirect($base,'المفتاح والاسم مطلوبان.');
 try{if($id>0){$s=$pdo->prepare('UPDATE site_content SET content_key=:k,group_key=:g,label=:l,value_ar=:ar,value_en=:en,input_type=:t,sort_order=:s,is_active=:a WHERE id=:id');$s->execute([':k'=>$key,':g'=>$group,':l'=>$label,':ar'=>$ar,':en'=>$en,':t'=>$type,':s'=>$sort,':a'=>$active,':id'=>$id]);$act='content.update';}else{$s=$pdo->prepare('INSERT INTO site_content(content_key,group_key,label,value_ar,value_en,input_type,sort_order,is_active) VALUES(:k,:g,:l,:ar,:en,:t,:s,:a)');$s->execute([':k'=>$key,':g'=>$group,':l'=>$label,':ar'=>$ar,':en'=>$en,':t'=>$type,':s'=>$sort,':a'=>$active]);$act='content.create';}cmsAudit($act,'site_content',$key);cmsAdminRedirect($base,'تم الحفظ.');}catch(PDOException $e){cmsAdminRedirect($base,'تعذر الحفظ. تأكد أن المفتاح غير مستخدم.');}}
$edit=null;if(($eid=cmsInt($_GET['edit']??0))>0){$s=$pdo->prepare('SELECT * FROM site_content WHERE id=:id');$s->execute([':id'=>$eid]);$edit=$s->fetch()?:null;}
$rows=$pdo->query('SELECT * FROM site_content ORDER BY group_key,sort_order,id')->fetchAll();cmsAdminHead('محتوى الموقع');cmsAdminSidebar('content');cmsAdminTopbar('محتوى الموقع');?>
<div class="content"><?php if($m=cmsAdminMessage()):?><div class="alert"><?=cmsE($m)?></div><?php endif;?><div class="split"><section class="card"><h2>العناصر</h2><div class="table-wrap"><table class="table"><thead><tr><th>المجموعة</th><th>المفتاح</th><th>الاسم</th><th>الحالة</th><th>الترتيب</th><th>إجراء</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=cmsE($r['group_key'])?></td><td><code><?=cmsE($r['content_key'])?></code></td><td><?=cmsE($r['label'])?></td><td><span class="pill <?=$r['is_active']?'ok':'bad'?>"><?=$r['is_active']?'ظاهر':'مخفي'?></span></td><td><?=intval($r['sort_order'])?></td><td><div class="actions"><a class="btn" href="?edit=<?=$r['id']?>">تعديل</a><form method="post"><?=cmsCsrfField()?><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn" name="action" value="toggle">إظهار/إخفاء</button><button class="btn danger" name="action" value="delete" onclick="return confirm('حذف العنصر؟')">حذف</button></form></div></td></tr><?php endforeach;?></tbody></table></div></section><section class="card"><h2><?=$edit?'تعديل عنصر':'إضافة عنصر'?></h2><form method="post"><?=cmsCsrfField()?><input type="hidden" name="id" value="<?=$edit['id']??0?>"><div class="form-grid"><label class="field"><span>المفتاح</span><input name="content_key" required value="<?=cmsE((string)($edit['content_key']??''))?>" placeholder="hero-title"></label><label class="field"><span>المجموعة</span><input name="group_key" value="<?=cmsE((string)($edit['group_key']??'general'))?>"></label><label class="field"><span>اسم إداري</span><input name="label" required value="<?=cmsE((string)($edit['label']??''))?>"></label><label class="field"><span>نوع الحقل</span><select name="input_type"><?php foreach(['text'=>'نص','textarea'=>'نص طويل','html'=>'HTML'] as $k=>$v):?><option value="<?=$k?>" <?=cmsSelected($edit['input_type']??'text',$k)?>><?=$v?></option><?php endforeach;?></select></label><label class="field"><span>العربية</span><textarea name="value_ar"><?=cmsE((string)($edit['value_ar']??''))?></textarea></label><label class="field"><span>English</span><textarea name="value_en"><?=cmsE((string)($edit['value_en']??''))?></textarea></label><label class="field"><span>الترتيب</span><input type="number" name="sort_order" value="<?=intval($edit['sort_order']??0)?>"></label><label class="module-row"><span>ظاهر</span><input class="check" type="checkbox" name="is_active" value="1" <?=cmsChecked($edit['is_active']??1)?>></label></div><div class="actions" style="margin-top:16px"><button class="btn primary">حفظ</button><?php if($edit):?><a class="btn" href="<?=$base?>">إلغاء</a><?php endif;?></div></form></section></div></div><?php cmsAdminEnd();
